from PIL import Image, ImageEnhance
img = Image.open('radiograph.jpg')
regions = {
 'F_UL_distal': (1600, 350, 2100, 700),
 'G_UR_wide':   (450, 340, 1100, 700),
}
for name,(x1,y1,x2,y2) in regions.items():
